L49_1.m_Talk_KOREA = "처음엔 웬 뚱냥이가 헬기를 조종하길래 내가 침식되어버린 건가 싶었는데, 다행히 그건 아닌 모양이야."
L49_1.m_fTalkTime = 0.03
L49_1.m_Talk_JPN = "妙な姿のデブ猫がヘリを操縦してるものだから、自分が侵食されたのかと思ったが、そうじゃなくてよかったぜ。"
L49_1.m_Talk_ENG = "At first, when I saw a chonker flying the chopper, I thought I'd been Corrupted, but guess not."
