L2_1 = {}
L2_1.m_CutScenKey_Talk = "OMEN_CHAMBER_INTERLUDE11@24#Talk"
L2_1.m_CutScenProcessKey = 0
L2_1.m_CutScenID = 7900124
L2_1.m_CutScenStrID = "OMEN_CHAMBER_INTERLUDE11"
L2_1.m_bWaitClick = true
L2_1.m_fWaitTime = 0
L2_1.m_Face = "UNIT_DESPAIR"
L2_1.m_CharStrID = "SAW_REAPER_NULL_NULL"
L2_1.m_Pos = "L"
L2_1.m_Talk_KOREA = "걘 뚱냥이가 아니라 여우…… 아니지, 내가 무슨 말을 하는 거람."
L2_1.m_fTalkTime = 0.03
L2_1.m_Talk_JPN = "あいつはデブ猫じゃなくて狐……って私何言ってるんだろ。"
L2_1.m_Talk_ENG = "Fluffox is not chonky, it's a fox– Wait, what am I saying?"
L2_1.m_Talk_TWN = "牠不是胖貓，而是狐狸……不對，我在說什麼？"
L2_1.m_Talk_DEU = "Fluffox is not chonky, it's a fox– Wait, what am I saying?"
L2_1.m_Talk_FRA = "Fluffox is not chonky, it's a fox– Wait, what am I saying?"
L3_1 = {}
L3_1.m_CutScenKey_Talk = "OMEN_CHAMBER_INTERLUDE11@25#Talk"
L3_1.m_CutScenProcessKey = 0
L3_1.m_CutScenID = 7900124
L3_1.m_CutScenStrID = "OMEN_CHAMBER_INTERLUDE11"
L3_1.m_bWaitClick = true
L3_1.m_fWaitTime = 0
L3_1.m_Face = "UNIT_SERIOUS"
L3_1.m_CharStrID = "SAW_REAPER_NULL_NULL"
L3_1.m_Pos = "L"
L3_1.m_Talk_KOREA = "어쨌든 본부 팀이 무사해서 다행이네요. IFF 신호에 응답이 없어서 최악의 상황까지 가정했거든요."
L3_1.m_fTalkTime = 0.03
L3_1.m_Talk_JPN = "とにかく、本部のチームが無事でよかったです。IFF信号に応答がないから、最悪の状況も考えてたんです。"
L3_1.m_Talk_ENG = "Anyway, glad HQ's intact. With no IFF reply we feared the worst."
L3_1.m_Talk_TWN = "總之，幸好本部隊伍平安無事，因為沒有回應IFF信號，我還假設最糟的情況了。"
L3_1.m_Talk_DEU = "Anyway, glad HQ's intact. With no IFF reply we feared the worst."
L3_1.m_Talk_FRA = "Anyway, glad HQ's intact. With no IFF reply we feared the worst."
L4_1 = {}
L4_1.m_CutScenKey_Talk = "OMEN_CHAMBER_INTERLUDE11@26#Talk"
L4_1.m_CutScenProcessKey = 0
L4_1.m_CutScenID = 7900124
L4_1.m_CutScenStrID = "OMEN_CHAMBER_INTERLUDE11"
L4_1.m_bWaitClick = true
L4_1.m_fWaitTime = 0
L4_1.m_CharStrID = "SAW_REAPER_NULL_NULL"
L4_1.m_Pos = "L"
L4_1.m_Talk_KOREA = "준비도 없이 대균열에 진입하면 어쩌나 싶었는데, 지금은 문제없겠어요."
L4_1.m_fTalkTime = 0.03
L4_1.m_Talk_JPN = "準備もなく大亀裂に進入することになったらどうしようって思っていましたが、これなら問題ありませんね。"
L4_1.m_Talk_ENG = "I worried we'd have to dive the Grand Dimension Crevice cold, but looks like we're fine now."
L4_1.m_Talk_TWN = "本來還在想要是毫無準備就進入大峽谷會怎麼樣，但現在應該沒問題。"
L4_1.m_Talk_DEU = "I worried we'd have to dive the Grand Dimension Crevice cold, but looks like we're fine now."
L4_1.m_Talk_FRA = "I worried we'd have to dive the Grand Dimension Crevice cold, but looks like we're fine now."
