L7_1.m_CutScenKey_Talk = "OMEN_CHAMBER_INTERLUDE11@27#Talk"
L7_1.m_CutScenProcessKey = 0
L7_1.m_CutScenID = 7900124
L7_1.m_CutScenStrID = "OMEN_CHAMBER_INTERLUDE11"
L7_1.m_bWaitClick = true
L7_1.m_fWaitTime = 0
L7_1.m_Face = "UNIT_IDLE"
L7_1.m_CharStrID = "JOHN_MASON_NULL_NULL"
L7_1.m_Pos = "L"
L7_1.m_Talk_KOREA = "별로 대단한 건 아니야. 이쪽은 합중국에서 받은 리액터를 달아준 게 전부니까."
L7_1.m_fTalkTime = 0.03
L7_1.m_Talk_JPN = "別に大したものじゃない。こっちは合衆国からもらったリアクターをつけただけだ。"
L7_1.m_Talk_ENG = "We didn't do much. Just bolted on a States-issued Reactor."
L7_1.m_Talk_TWN = "這沒什麼了不起，我們只不過是裝了從合眾國那邊得到的反應器。"
L7_1.m_Talk_DEU = "We didn't do much. Just bolted on a States-issued Reactor."
L7_1.m_Talk_FRA = "We didn't do much. Just bolted on a States-issued Reactor."
L8_1 = {}
L8_1.m_CutScenKey_Talk = "OMEN_CHAMBER_INTERLUDE11@28#Talk"
L8_1.m_CutScenProcessKey = 0
