L8_1.m_Talk_KOREA = "그런데, 그렇게 멋대로 움직여도 되는 건가?"
L8_1.m_fTalkTime = 0.03
L8_1.m_Talk_JPN = "しかし、そんなにすぐ動いてもいいのか？"
L8_1.m_Talk_ENG = "But are you sure you should be moving around like that?"
L8_1.m_Talk_TWN = "不過可以這樣任意移動嗎？"
